import React, { FC } from "react";
import { graphql, HeadFC, PageProps } from "gatsby";
import IndexContents from "../components/index/contents";
import SEO from '../components/SEO'
import { Recommend } from "../types/recommend";
import { FaXTwitter } from "react-icons/fa6";
import { GoLinkExternal } from "react-icons/go";

type siteMetadata = {
  title: string;
  description: string;
  siteUrl: string;
};

export const query = graphql`
  query IndexPage {
    site {
      siteMetadata {
        title
        description
        siteUrl
      }
    }
    recommend {
      recommend {
        no
        id
      }
    }
  }
`;

const IndexPage: FC<PageProps<any>> = ({ data }) => {
  const recommend: Recommend[] = data.recommend.recommend;

  return (
    <>
      <main className="relative bg-transparent mx-auto inset-auto w-screen">
        <IndexContents
          recommend={recommend}
        />
      </main>
      <footer className="relative bg-theme text-white pt-5 h-40">
        <ul className="flex justify-around py-3">
          <li>
            <a
              href="https://twitter.com/twilightplc"
              target="_blank"
              className="flex justify-between items-end"
            >
              <FaXTwitter className="font-bold text-xl" />
              <p className="flex items-center ml-2 text-sm">
                <span>(非公式ファンサイト運営)</span>
                <GoLinkExternal className="ml-1 font-bold" />
              </p>
            </a>
          </li>
        </ul>
        <div className="text-center py-3 text-[#27489b]">
          <p className="text-xs">&copy;&nbsp;2023&nbsp;Pochi</p>
        </div>
      </footer>
    </>
  );
};

export default IndexPage;

export const Head: HeadFC<any> = ({ data }) => {
  const siteMetadata: siteMetadata = data.site.siteMetadata;
  // ?section=place などのクエリがあればセクション別タイトル/OGに反映
  // Gatsby v5 の Head の location は pathname しか持たないため、ブラウザ側で
  // 取得できる場合のみ参照する
  const search =
    typeof window !== "undefined" && typeof window.location?.search === "string"
      ? window.location.search
      : "";
  const section = (() => {
    const m = search.match(/[?&]section=([^&]+)/);
    return m ? decodeURIComponent(m[1]) : undefined;
  })();
  return (
    <SEO
      title={siteMetadata.title}
      description={siteMetadata.description}
      path="/"
      section={section}
    />
  );
};
